function extractGeminiText(item) {
  const j = item.json || {};
  if (j.content && Array.isArray(j.content.parts)) {
    return j.content.parts.map(p => p.text || '').join('');
  }
  if (typeof j.content === 'string') return j.content;
  return '';
}
function extractNimText(item) {
  const j = item.json || {};
  if (Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) {
    return j.choices[0].message.content || '';
  }
  return '';
}
function parseJsonLoose(text) {
  const cleaned = (text || '').replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (e) { return null; }
}
let raw = '';
let triageSource = 'gemini';
try {
  const geminiText = extractGeminiText($('Triage').item);
  if (geminiText) raw = geminiText;
} catch (e) { /* Triage branch didn't run in this execution path */ }
if (!raw) {
  try {
    raw = extractNimText($('Triage Fallback (NIM)').item);
    triageSource = 'llama_nim_fallback';
  } catch (e) { /* neither ran, shouldn't happen */ }
}
const parsed = parseJsonLoose(raw) || {};
return [{
  json: {
    ...$('Code in JavaScript').item.json,
    relevanceScore: parsed.relevance_score ?? 0,
    format: parsed.format || 'Carousel',
    contentPillar: parsed.content_pillar || 'Market Watch',
    objectiveTag: parsed.objective_tag || 'Save',
    triageReason: parsed.reason || '',
    triageSource,
  },
}];

