const text = ($json.content && Array.isArray($json.content.parts)) ? $json.content.parts.map(p => p.text || '').join('') : '';

const KEYWORDS = ['cheapest','cheaper','first','only','best','fastest','largest','smallest','lightest','most affordable','most powerful','most expensive','top','leading','biggest','highest','lowest','newest'];

function extractEnStrings(obj, out) {
  if (obj == null) return;
  if (Array.isArray(obj)) { obj.forEach(v => extractEnStrings(v, out)); return; }
  if (typeof obj === 'object') {
    for (const [k, v] of Object.entries(obj)) {
      if (typeof v === 'string' && /_en$/.test(k)) out.push(v);
      else extractEnStrings(v, out);
    }
  }
}

let enStrings = [];
try {
  const cleaned = text.replace(/```json/gi, '').replace(/```/g, '');
  const draft = JSON.parse(cleaned);
  extractEnStrings(draft, enStrings);
} catch (e) {
  // draft JSON didn't parse cleanly - fall back to scanning the raw text so extraction still runs
  enStrings = [text];
}

const sentences = enStrings.join(' ').split(/(?<=[.!?])\s+|\n+/).map(s => s.trim()).filter(s => s.length > 5);

// dedupe by matched keyword (not by sentence text) - a draft repeats the same superlative
// across hook/slides/every platform caption, and we only want to search it once. Keep the
// longest matching sentence per keyword since it usually carries the most search-useful context.
const byKeyword = {};
for (const s of sentences) {
  const lower = s.toLowerCase();
  for (const kw of KEYWORDS) {
    if (lower.includes(kw)) {
      if (!byKeyword[kw] || s.length > byKeyword[kw].length) {
        byKeyword[kw] = s;
      }
    }
  }
}

// cap at 5 claims/article - cost and latency bound, documented in CLAUDE.md
const claims = Object.entries(byKeyword).slice(0, 5).map(([keyword, sentence]) => ({ keyword, text: sentence }));

return [{
  json: {
    content: $json.content,
    contentCreationSource: $json.contentCreationSource,
    claims,
    claimCount: claims.length,
  },
}];

const claim = $('Split Out Claims').item.json.claims;
return {
  json: {
    claim: claim.text,
    keyword: claim.keyword,
    tavilyAnswer: $json.answer || null,
    tavilySources: (Array.isArray($json.results) ? $json.results : []).slice(0, 3).map(r => ({
      title: r.title,
      url: r.url,
      content: (r.content || '').slice(0, 300),
    })),
    tavilyError: $json.error !== undefined,
  },
};

const tavilyResults = $json.tavilyResults || [];
let groundingContext = '';
if (tavilyResults.length > 0) {
  const lines = tavilyResults.map((r, i) => {
    if (r.tavilyError) {
      return `${i + 1}. Claim ("${r.keyword}"): "${r.claim}"\n   Search failed - treat as unresolved, use [UNVERIFIED - requires external check].`;
    }
    const sources = (r.tavilySources || []).map(s => `${s.title} (${s.url}): ${s.content}`).join('\n   ');
    return `${i + 1}. Claim ("${r.keyword}"): "${r.claim}"\n   Tavily answer: ${r.tavilyAnswer || 'none'}\n   Sources:\n   ${sources || 'none'}`;
  });
  groundingContext = `SEARCH-GROUNDED CLAIM CHECKS (retrieved via Tavily before this audit, for the specific superlative/comparative claims below only - judge ONLY these claims using this retrieved evidence, not your own knowledge):\n\n${lines.join('\n\n')}\n\nFor each claim above: if the evidence clearly supports it, mark [VERIFIED - <source domain>]. If the evidence clearly contradicts it, mark [CONTRADICTED - <source domain>: <correct value>]. If the evidence is missing, inconclusive, or the search failed, keep [UNVERIFIED - requires external check]. Do not invent a verdict beyond what the evidence above actually shows.`;
} else {
  groundingContext = '(No superlative/comparative claims were detected for search-grounding in this draft - audit all claims per your normal sourcing rules below.)';
}
return [{
  json: {
    groundingContext,
    tavilyResults,
  },
}];

// Turns Content Creation's variable-length draftCarouselSlides into a concrete, numbered
// slide plan: cover (always slide 1) + one slide per content beat + cta (always the last
// slide). Slide count is entirely content-driven - whatever Content Creation actually wrote -
// capped only by Instagram's real 10-slide carousel limit, never padded to a fixed target.
const draft = $json;
const rawSlides = Array.isArray(draft.draftCarouselSlides) ? draft.draftCarouselSlides : [];

const MAX_TOTAL_SLIDES = 10; // Instagram's actual carousel limit
const MAX_CONTENT_SLIDES = MAX_TOTAL_SLIDES - 2; // reserve cover (1) + cta (1)
const VALID_ROLES = ['hero_stat', 'spec', 'pro', 'con', 'comparison'];

const capApplied = rawSlides.length > MAX_CONTENT_SLIDES;
const contentSlides = rawSlides.slice(0, MAX_CONTENT_SLIDES);
const totalSlides = contentSlides.length + 2;

const plan = [];

plan.push({
  slideNumber: 1,
  totalSlides,
  role: 'cover',
  slideContent: contentSlides[0] || rawSlides[0] || {},
});

contentSlides.forEach((sc, i) => {
  const role = VALID_ROLES.includes(sc.slide_role) ? sc.slide_role : 'spec';
  plan.push({
    slideNumber: i + 2,
    totalSlides,
    role,
    slideContent: sc,
  });
});

plan.push({
  slideNumber: totalSlides,
  totalSlides,
  role: 'cta',
  slideContent: { skip_if_ar: draft.draftSkipIf },
});

return [{
  json: {
    ...draft,
    slidePlan: plan,
    totalSlides,
    rawContentSlideCount: rawSlides.length,
    capApplied,
  },
}];

