parameters.jsCode:
// Deduplicate by normalized title (within this batch), then tag every item with:
// - normalizedKey: rough brand+model fingerprint, used for cross-source dedupe lookups
// - postId: unique id threaded through the rest of the pipeline for Sheet row matching

const BRANDS = [
  'toyota','hyundai','kia','chery','mg','byd','geely','jetour','changan','gac','nissan',
  'chevrolet','peugeot','citroen','citroën','renault','fiat','skoda','volkswagen','vw','bmw',
  'mercedes','audi','honda','mazda','suzuki','mitsubishi','ford','jeep','opel','seat','cupra',
  'exeed','deepal','gwm','haval','tesla','volvo','lexus','infiniti','genesis','dongfeng','jac',
  'baic','zeekr','xpeng','nio','im','li','aito','porsche','land rover','range rover','jaguar',
  'bugatti','ferrari','lamborghini','maserati','bentley','rolls-royce','cadillac','buick',
  'mansour','contactcars'
];

function normalizeKey(title) {
  const lower = (title || '').toLowerCase();
  // \p{L}/\p{N} (Unicode letter/number, any script) instead of \w ([A-Za-z0-9_] only) -
  // \w silently stripped every Arabic character to a space, so any purely-Arabic title
  // with no embedded digit or Latin brand name collapsed to the same empty-string key
  // (confirmed live 2026-08-15: two real, unrelated Arabic articles both produced "").
  // This only strips actual punctuation/symbols now, same as before; Latin-text behavior
  // is unchanged since \p{L}\p{N} is a superset of \w for basic Latin (kept the explicit
  // _ to match \w exactly).
  const words = lower.replace(/[^\p{L}\p{N}_\s]/gu, ' ').split(/\s+/).filter(Boolean);
  const brandIdx = words.findIndex(w => BRANDS.includes(w));
  if (brandIdx === -1) {
    // fallback: first 6 significant words of the normalized title
    return words.slice(0, 6).join(' ');
  }
  // brand + next up-to-3 tokens (rough model/trim guess) + any 4-digit year in the title
  const yearMatch = lower.match(/\b(20\d{2})\b/);
  const modelTokens = words.slice(brandIdx, brandIdx + 4);
  return modelTokens.join(' ') + (yearMatch ? ' ' + yearMatch[1] : '');
}

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const seen = new Set();
const output = [];

for (const item of $input.all()) {
  if (!item.json || !item.json.title) continue; // guard against stray/null items from un-fired branches
  const normalized = item.json.title
    .toLowerCase()
    .replace(/[^\w\s]/g, '')
    .split(' ')
    .slice(0, 10)
    .join(' ');

  if (!seen.has(normalized)) {
    seen.add(normalized);
    output.push({
      json: {
        ...item.json,
        normalizedKey: normalizeKey(item.json.title),
        postId: uuidv4(),
      },
    });
  }
}

return output;

